raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBGL-K-preferential_rate-01",
   "status": "OK",
   "label": "우대이율 적용 조건 - 입금 건수 기준",
   "source": {
    "quote": "| 결산일 전월 말일 기준 직전 3개월 동안 입금된 건수 | 적용이율 (기본이율+우대이율, 2016.11.12 기준) |\n| --- | --- |\n| 9건 이상 | 연1.5% |\n| 6건 이상 ~ 8건 이하 | 연1.0% |\n| 1건 이상 ~ 5건 이하 | 연0.5% |"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -4,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "count_distinct_months": {
      "event": "DEPOSIT",
      "within": {
       "ref": "$window"
      },
      "where": {
       "in": [
        {
         "var": "event.detail.type"
        },
        [
         "① 4대연금",
         "② 기타연금",
         "③ 국가보훈처",
         "④ KB골든라이프 공사주택연금론",
         "④ KB골든라이프 주택연금론",
         "⑤ KB국민은행 연금신탁",
         "⑥ KB국민은행 퇴직연금",
         "⑦ KB골든라이프연금우대예금"
        ]
       ]
      }
     }
    }
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": {
      "">=": [
       {
        "var": "count_distinct_months"
       },
       9
      ],
      "and": {
       "">=": [
        {
         "var": "count_distinct_months"
        },
        6
       ],
       "<=": [
        {
         "var": "count_distinct_months"
        },
        8
       ]
      },
      "and": {
       "">=": [
        {
         "var": "count_distinct_months"
        },
        1
       ],
       "<=": [
        {
         "var": "count_distinct_months"
        },
        5
       ]
      }
     },
     "unit": "YEAR"
    }
   }
  },
  {
   "rule_id": "R-KBGL-K-preferential_rate-02",
   "status": "OK",
   "label": "우대이율 적용 금액 제한",
   "source": {
    "quote": "적용금액 : 이 통장의 결산기 평균잔액 중 1백만원 이하의 금액까지는 우대이율을 적용 하며, 1백만원을 초과하는 금액에 대하여는 기본이율을 적용"
   },
   "condition": {
    ">": [
     {
      "var": "account.balance"
     },
     1000000
    ]
   },
   "effect": {
    "type": "RATE_SUBTRACT",
    "value": {
      "var": "contract.base_rate"
    },
    "unit": "YEAR"
   }
  }
 ]
}

