raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBGL-K-interest_payment-01",
   "status": "OK",
   "label": "이자지급시기",
   "source": {
    "quote": "▪ 매년 2월, 5월, 8월, 11월의 둘째 금요일에 결산하여 다음날 원금에 더함"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "account.last_transaction_date"
       },
       [
        {
         "anchor": "contract.reference_date",
         "month_of": [2, 5, 8, 11],
         "day": {
          "weekday": "FRI",
          "nth": 2
         }
        }
       ]
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.termination_type"
        },
        [
         "MATURITY",
         "EARLY",
         "PARTIAL",
         "MID_TERM"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "INTEREST_PAID"
   }
  },
  {
   "rule_id": "R-KBGL-K-interest_payment-02",
   "status": "OK",
   "label": "이자지급시기 — 최종거래일 이후 이자 계산",
   "source": {
    "quote": "※ 예금의 이자는 최종거래일로부터 5년이 경과한 날부터는 이자를 원금에 더하지 않고, 계좌해지 또는 추가 입출금 거래 발생일에 일괄 계산하여 지급할 수 있습니다"
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "var": "account.last_transaction_date"
       },
       {
        "anchor": "contract.reference_date",
        "offset_months": -60,
        "day": "last"
       }
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.termination_type"
        },
        [
         "MATURITY",
         "EARLY",
         "PARTIAL",
         "MID_TERM"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "INTEREST_PAID_ON_CLOSURE"
   }
  }
 ]
}

