raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBNR-K-preferential_rate-01",
   "status": "OK",
   "label": "우대이율 적용 조건",
   "source": {
    "quote": "적용대상: 이 통장 가입자가 결산일의 전월 말일을 기준으로 직전 3 개월 동안 2 개월 이상 다음 각 호의 1 에 해당하는 경우 연 1.9%p 우대이율을 적용합니다."
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -3,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    ">=": [
     {
      "count_distinct_months": {
       "event": "SALARY_TRANSFER",
       "within": {
        "ref": "$window"
       }
      }
     },
     2
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 1.9,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-KBNR-K-preferential_rate-02",
   "status": "OK",
   "label": "우대이율 적용 한도",
   "source": {
    "quote": "적용한도 : 이 통장의 결산기 평균잔액 중 100만원 이하의 금액까지는 기본이율과 우대이율을 합산하여 적용하며, 100만원을 초과하는 금액은 기본이율만 적용"
   },
   "condition": {
    "and": [
     {
      "var": "account.balance"
     },
     {
      "op": "<=",
      "right": 1000000
     }
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "BASIC_RATE + 1.9%",
    "unit": "PERCENT"
   }
  }
 ]
}

