   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "or": [
     {
      "exists": {
       "event": "AUTO_TRANSFER",
       "within": {
        "ref": "$window"
       }
      }
     },
     {
      "exists": {
       "event": "CARD_USAGE",
       "within": {
        "ref": "$window"
       }
      }
     }
    ]
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "EBANK_TRANSFER",
    "value": "UNLIMITED"
   }
  },
  {
   "rule_id": "R-KBNR-K-fee-02",
   "status": "OK",
