{
 "rules": [
  {
   "rule_id": "R-KBMY-K-preferential_rate-01",
   "status": "OK",
   "label": "급여이체 우대이율",
   "source": {
    "quote": "1 | 급여이체 | 이 적금의 신규일이 포함된 달부터 3개월이 경과한 달까지 50만원 이상 급여이체 실적주1)이 발생한 월수가 1개월 이상인 경우"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.start_date",
       "offset_months": 2,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "count_distinct_months": {
      "event": "SALARY_TRANSFER",
      "within": {
       "ref": "$window"
      },
      "where": {
       "min_amount": 500000
      }
    },
    ">=": [
     1
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-KBMY-K-preferential_rate-02",
   "status": "OK",
   "label": "카드결제계좌 우대이율",
   "source": {
    "quote": "2 | 카드결제계좌 | 이 적금의 신규일로부터 3개월이 속한 달의 말일 기준으로 KB국민카드 결제계좌가 KB국민은행 입출금이자유로운예금인 경우"
   },
   "condition": {
    "in": [
     {
      "var": "customer.held_products"
     },
     [
