    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-KBMY-K-preferential_rate-03",
   "status": "OK",
   "label": "자동이체 저축 우대이율",
   "source": {
    "quote": "3 | 자동이체 저축 | 이 적금의 계약기간에 해당하는 개월 수 이상 회차를 납입한 계좌 중 총 납입 회차의 2/3 이상을 자동이체 등 창구 이외의 채널을 이용하여 입금한 경우"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.maturity_date",
       "offset_months": 0,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "count_events": {
     "event": "DEPOSIT",
     "within": {
      "ref": "$window"
     },
     "where": {
      "not": {
       "in": [
        {
         "var": "event.channel"
        },
        [
         "BRANCH"
        ]
       ]
      }
     }
    },
    ">=": [
     {
      "divide": [
       {
        "count_events": {
         "event": "DEPOSIT",
         "within": {
          "ref": "$window"
         }
        }
       },
       3
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-KBMY-K-preferential_rate-04",
   "status": "OK",
   "label": "아파트관리비 이체 우대이율",
